import {notificationHealth} from './notification-health.ts';
import {checkNewPassword} from './password-security.ts';
import {boundedRequest} from './request-body.ts';
import {capacityRoute} from './capacity.ts';
import {orderEditRoute} from './order-edit.ts';
import {workflowRoute} from './order-workflow.ts';
import {enqueueOrderWhatsApp,processOrderWhatsApp,whatsappConfigured,type WhatsAppEnv} from './whatsapp.ts';
import {z,ZodError} from 'zod';
import {PRODUCTS,type Product,localToday} from './catalog.ts';
import {calculateOrder} from './order.ts';
export type Env=WhatsAppEnv & {SUPABASE_URL:string;SUPABASE_ANON_KEY:string;SUPABASE_SERVICE_ROLE_KEY:string;RESEND_API_KEY?:string;EMAIL_FROM?:string;SITE_URL?:string;META_ACCESS_TOKEN?:string;META_GRAPH_VERSION?:string};
import {HttpError} from './errors.ts';
import {dispatchMarketing,attribution,couponDiscount,processMarketing} from './marketing.ts';
export const BANK={alias:'',cbu:'',holder:'',bank:''};

export function paymentState(total:number,paid:number,status:string){if(paid<=0)return 'Sin pago';if(paid<Math.ceil(total/2))return 'Seña parcial';if(paid>=total)return 'Pagado total';if(status==='en_produccion'||status==='entregado')return 'Saldo pendiente';return paid===Math.ceil(total/2)?'Seña completa':'Saldo pendiente';}
export function paymentStage(total:number,deposit:number,paid:number,payments:{estado:string}[]=[]){
 if(paid>=total&&total>0)return 'saldo_pagado';
 if(payments.some(p=>p.estado==='comprobante_enviado'))return 'comprobante_recibido';
 if(paid>=deposit&&deposit>0)return 'sena_verificada';
 return 'pendiente';
}
export function normalizedPhone(value:string){let d=value.replace(/\D/g,'');const fail=()=>{throw new HttpError(400,'Ingresá un WhatsApp argentino con código de área. Ej.: +54 9 385 6870303.');};if(d.startsWith('0054'))d=d.slice(2);if(value.trim().startsWith('+')&&!d.startsWith('54'))fail();if(d.startsWith('549')&&d.length===13&&/[1-9]/.test(d[3]))return '+'+d;if(d.startsWith('54')&&d.length===12&&/[1-9]/.test(d[2]))return '+549'+d.slice(2);if(d.startsWith('0'))d=d.slice(1);if(d.length===12){for(const n of [2,3,4])if(d.slice(n,n+2)==='15'){d=d.slice(0,n)+d.slice(n+2);break;}}if(d.length===10&&/^[1-9]/.test(d))return '+549'+d;return fail();}
export function checkFile(bytes:Uint8Array,type:string){if(bytes.length===0||bytes.length>5242880)throw new HttpError(400,'El comprobante debe pesar hasta 5 MB.');const pdf=bytes[0]===37&&bytes[1]===80&&bytes[2]===68&&bytes[3]===70;const jpeg=bytes[0]===255&&bytes[1]===216&&bytes[2]===255;const png=[137,80,78,71,13,10,26,10].every((v,i)=>bytes[i]===v);const webp=String.fromCharCode(...bytes.slice(0,4))==='RIFF'&&String.fromCharCode(...bytes.slice(8,12))==='WEBP';if(!({ 'application/pdf':pdf,'image/jpeg':jpeg,'image/png':png,'image/webp':webp} as Record<string,boolean>)[type])throw new HttpError(400,'Subí un archivo JPG, PNG, WebP o PDF válido.');}
export function publicPayment(p:any){return {id:p.id,tipo:p.tipo,monto_esperado:Number(p.monto_esperado),monto_recibido:Number(p.monto_recibido),estado:p.estado,fecha_pago:p.fecha_pago,numero_operacion:p.numero_operacion,diferencia:Number(p.diferencia),hasReceipt:!!p.comprobante,rejectionReason:p.estado==='rechazado'?String(p.notas||''):undefined};}
export async function digest(value:string|Uint8Array){const bytes=typeof value==='string'?new TextEncoder().encode(value):value;const result=await crypto.subtle.digest('SHA-256',bytes as BufferSource);return Array.from(new Uint8Array(result)).map(v=>v.toString(16).padStart(2,'0')).join('');}
export function createHandler(env:Env,transport:typeof fetch=fetch){
 const origins=['https://ploprecibidas.com.ar','https://www.ploprecibidas.com.ar','https://plop-recibidas-tienda.abuzzflea1.chatgpt.site','https://ploprecibidas-oficial.netlify.app','https://plop-recibidas.pages.dev'];
 const allowedOrigin=(origin:string)=>origins.includes(origin)||/^https:\/\/(?:deploy-preview-\d+|[a-f0-9]{24})--ploprecibidas-oficial\.netlify\.app$/.test(origin);
 const headersService={apikey:env.SUPABASE_SERVICE_ROLE_KEY,Authorization:`Bearer ${env.SUPABASE_SERVICE_ROLE_KEY}`,'Content-Type':'application/json'};
 async function rest(path:string,options:RequestInit={}){const r=await transport(env.SUPABASE_URL+'/rest/v1/'+path,{...options,headers:{...headersService,...options.headers},signal:AbortSignal.timeout(15000)});const d=await r.json().catch(()=>null);if(!r.ok){if(d?.message?.includes('workflow_forbidden'))throw new HttpError(403,'Solo el equipo autorizado puede gestionar el pedido.');if(d?.message?.includes('workflow_conflict'))throw new HttpError(409,'El pedido o sus pagos cambiaron. Actualizá la ficha antes de guardar nuevamente.');if(d?.message?.includes('workflow_key_reused'))throw new HttpError(409,'Este reintento no coincide con el cambio original. Actualizá la ficha.');if(d?.message?.includes('workflow_reason_required'))throw new HttpError(400,'Escribí el motivo para cancelar, reactivar o quitar la aprobación del diseño.');if(d?.message?.includes('workflow_no_changes'))throw new HttpError(400,'No hay cambios de estado, diseño o notas para guardar.');if(d?.message?.includes('workflow_invalid'))throw new HttpError(400,'Revisá el estado, el diseño y las notas del pedido.');if(d?.message?.includes('workflow_not_found'))throw new HttpError(404,'No encontramos ese pedido activo.');if(d?.message?.includes('order_edit_conflict'))throw new HttpError(409,'El pedido cambió mientras lo editabas. Cerrá esta ventana y actualizá el panel antes de volver a editar.');if(d?.message?.includes('order_edit_key_reused'))throw new HttpError(409,'Ese reintento no coincide con el cambio original. Volvé a abrir el pedido.');if(d?.message?.includes('order_edit_unavailable'))throw new HttpError(409,'No se puede editar un pedido cancelado o archivado. Revisá su estado primero.');if(d?.message?.includes('order_edit_not_found'))throw new HttpError(404,'No encontramos el pedido.');if(d?.message?.includes('order_edit_no_changes'))throw new HttpError(400,'Cambiá al menos un producto o la fecha para guardar.');if(d?.message?.includes('order_edit_invalid_date'))throw new HttpError(400,'Elegí una fecha válida con al menos dos días de anticipación.');if(d?.message?.includes('order_edit_date_full'))throw new HttpError(409,'El día elegido está completo. Elegí otra fecha; el pedido conserva su fecha y productos anteriores.');if(d?.message?.includes('order_edit_invalid_items'))throw new HttpError(400,'Revisá los productos, variantes y cantidades del pedido.');if(d?.message?.includes('order_edit_forbidden'))throw new HttpError(403,'Solo el equipo autorizado puede editar pedidos.');if(d?.message?.includes('invalid_coupon')||d?.message?.includes('coupon_product_mismatch'))throw new HttpError(400,'El cupón venció, alcanzó su límite o no aplica. Revisá tu pedido.');if(d?.message?.includes('cart_price_changed'))throw new HttpError(409,'Los precios cambiaron. Recargá y revisá tu pedido.');if(d?.message?.includes('qr_customer_already_used'))throw new HttpError(409,'Ya tenés un beneficio de esta campaña reservado o utilizado con ese WhatsApp. Un beneficio por cliente.');if(d?.message?.includes('qr_reservation_expired'))throw new HttpError(409,'La reserva del descuento venció. Escaneá nuevamente un QR disponible para armar otro pedido.');if(d?.message?.includes('date_unavailable'))throw new HttpError(409,'Esta fecha no está disponible. Elegí otra fecha de retiro.');if(d?.message?.includes('capacity_approval_required'))throw new HttpError(409,'Este día está completo. Autorizá primero el cupo adicional del pedido.');if(d?.message?.includes('capacity_request_changed'))throw new HttpError(409,'Esta solicitud ya fue resuelta. Actualizá el calendario.');if(d?.message?.includes('capacity_approval_forbidden'))throw new HttpError(403,'Solo el administrador autorizado puede aprobar un cupo adicional.');if(d?.message?.includes('capacity_note_required'))throw new HttpError(400,'Agregá un motivo para la decisión.');if(d?.code==='23505')throw new HttpError(409,'Ese número de operación o comprobante ya fue registrado.');if(d?.message?.includes('deposit_required'))throw new HttpError(400,'Verificá la seña antes de pasar el pedido a producción.');if(d?.message?.includes('balance_required'))throw new HttpError(400,'El saldo debe estar verificado antes de entregar.');if(d?.message?.includes('design_required'))throw new HttpError(400,'Confirmá la aprobación del diseño antes de producir.');if(d?.message?.includes('too_many_orders'))throw new HttpError(429,'Recibimos varias solicitudes. Esperá un momento o escribinos por WhatsApp.');if(d?.message?.includes('difference_note_required'))throw new HttpError(400,'Registrá una nota que explique la diferencia de monto.');if(d?.message?.includes('payment_not_needed'))throw new HttpError(400,'Ese importe ya está cubierto por pagos verificados.');console.error('plop_db_error',r.status,d?.code);throw new HttpError(503,'No pudimos guardar los cambios. Intentá nuevamente.');}return d;}
 async function relatedRecords(table:string,orders:any[],sort:string){const rows:any[]=[];for(let start=0;start<orders.length;start+=100){const ids=orders.slice(start,start+100).map(o=>encodeURIComponent(o.id)).join(',');for(let offset=0;;offset+=500){const page=await rest(`${table}?pedido_id=in.(${ids})&select=*&order=${sort}&limit=500&offset=${offset}`);if(rows.length+page.length>20000)throw new HttpError(503,'Este período tiene demasiados movimientos para cargarlo completo. No se muestran totales parciales; contactá al equipo para exportar el período.');rows.push(...page);if(page.length<500)break;}}return rows;}
 async function allowedStaff(email:string){return await rest("rpc/plop_staff_email",{method:"POST",body:JSON.stringify({p_email:email.toLowerCase()})})===true;}
 async function config(){const rows=await rest('plop_settings?key=eq.public&select=value');return {...BANK,leadDays:7,reminderHours:null,balanceDays:null,...(rows[0]?.value||{}),notificationsConfigured:!!(env.RESEND_API_KEY&&env.EMAIL_FROM),whatsappConfigured:whatsappConfigured(env)};}
 async function products(){const rows=await rest('plop_catalog?select=id,data,price,available');return rows.map((r:{id:string;data:Product;price:number;available:boolean})=>({...r.data,id:r.id,image:r.data.image,price:Number(r.price),available:r.available})) as Product[];}
 async function read(req:Request){const raw=await req.text();if(raw.length>65000)throw new HttpError(413,'La solicitud es demasiado grande.');try{return JSON.parse(raw)}catch{throw new HttpError(400,'No pudimos leer la solicitud.')}}
 async function user(req:Request,staff=false){const auth=req.headers.get('Authorization')||'';if(!auth.startsWith('Bearer '))throw new HttpError(401,'Volvé a ingresar para continuar.');let r:Response;try{r=await transport(env.SUPABASE_URL+'/auth/v1/user',{headers:{apikey:env.SUPABASE_ANON_KEY,Authorization:auth},signal:AbortSignal.timeout(12000)});}catch{throw new HttpError(503,'No pudimos comprobar tu sesión por un problema temporal. Volvé a intentar.');}if([400,401,403].includes(r.status))throw new HttpError(401,'Tu sesión venció. Volvé a ingresar.');if(!r.ok)throw new HttpError(503,'No pudimos comprobar tu sesión por un problema temporal. Volvé a intentar.');const u=await r.json().catch(()=>null);if(!u?.id)throw new HttpError(503,'No pudimos comprobar tu sesión por un problema temporal. Volvé a intentar.');if(staff&&(u.is_anonymous||!u.email_confirmed_at||!await allowedStaff(String(u.email))))throw new HttpError(403,'Este panel está reservado al equipo autorizado de Plop.');return u;}
 async function rate(req:Request,label:string,limit=20,seconds=60){const ip=req.headers.get('x-forwarded-for')?.split(',')[0]||req.headers.get('cf-connecting-ip')||'unknown';const ok=await rest('rpc/plop_rate_limit',{method:'POST',body:JSON.stringify({p_key:label+':'+await digest(ip),p_limit:limit,p_seconds:seconds})});if(!ok)throw new HttpError(429,'Esperá un momento antes de volver a intentar.');}
 async function orderFor(req:Request,id:string,bodyToken?:string){z.string().uuid().parse(id);const u=await user(req);const key=bodyToken||req.headers.get('x-order-token');if(!z.string().uuid().safeParse(key).success)throw new HttpError(404,'Necesitás el enlace privado de tu pedido.');const rows=await rest('plop_orders?id=eq.'+id+'&select=*');const o=rows[0];if(!o||o.request_key!==key)throw new HttpError(404,'Necesitás el enlace privado de tu pedido.');return {o,u};}
 function redactedOrder(o:any,payments:any[]=[]){return {id:o.code,uuid:o.id,status:o.status,total:Number(o.total),deposit:Number(o.deposit),paid:Number(o.verified_paid),subtotal:Number(o.subtotal||o.total),couponExpiresAt:o.coupon_expires_at,couponCode:o.coupon_code,discount:Number(o.discount||0),paymentStage:paymentStage(Number(o.total),Number(o.deposit),Number(o.verified_paid),payments),paymentState:paymentState(Number(o.total),Number(o.verified_paid),o.status),reserved:!!o.reserved_at,capacityStatus:o.capacity_status||'accepted',items:o.items,created_at:o.created_at,updated_at:o.updated_at,payments:payments.map(publicPayment)};}
 async function processJobs(){const whatsapp=await processOrderWhatsApp(rest,env,transport);const extras=await processMarketing({rest,user,rate,read,products,config,env,transport,normalizePhone:normalizedPhone,checkFile,orderFor});if(!env.RESEND_API_KEY||!env.EMAIL_FROM)return {sent:0,pendingConfiguration:true,...extras,...whatsapp};const conf=await config();let queued=0;
  await rest('plop_notifications?event=neq.whatsapp_pedido_nuevo&status=eq.sending&claimed_at=lt.'+new Date(Date.now()-600000).toISOString(),{method:'PATCH',body:JSON.stringify({status:'pending'})});const open=await rest("plop_orders?is_test=eq.false&status=in.(nuevo,en_revision,sena_recibida,en_produccion)&select=*");
  for(const o of open){const hours=(Date.now()-Date.parse(o.created_at))/3600000;const until=(Date.parse(o.contact.date+'T12:00:00-03:00')-Date.now())/86400000;
   if(conf.reminderHours&&hours>=conf.reminderHours&&Number(o.verified_paid)<Number(o.deposit)){await rest('plop_notifications?on_conflict=dedupe_key',{method:'POST',headers:{Prefer:'resolution=ignore-duplicates'},body:JSON.stringify({pedido_id:o.id,event:'seña_pendiente',dedupe_key:'seña:'+o.id})});queued++;}
   if(conf.balanceDays&&until<=conf.balanceDays&&until>=0&&Number(o.verified_paid)<Number(o.total)){await rest('plop_notifications?on_conflict=dedupe_key',{method:'POST',headers:{Prefer:'resolution=ignore-duplicates'},body:JSON.stringify({pedido_id:o.id,event:'saldo_pendiente',dedupe_key:'saldo:'+o.id})});queued++;}}
  const jobs=await rest('plop_notifications?event=neq.whatsapp_pedido_nuevo&status=in.(pending,failed)&attempts=lt.5&order=created_at.asc&limit=20');let sent=0;
  for(const job of jobs){const claim=await rest('plop_notifications?id=eq.'+job.id+'&status=in.(pending,failed)',{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({status:'sending',claimed_at:new Date().toISOString(),attempts:job.attempts+1})});if(!claim.length)continue;
   try{const o=(await rest('plop_orders?id=eq.'+job.pedido_id+'&select=*'))[0];if(!o||o.is_test||o.status==='cancelado'){await rest('plop_notifications?id=eq.'+job.id,{method:'PATCH',body:JSON.stringify({status:'failed',attempts:5,last_error:'Pedido de prueba, cancelado o inexistente: no enviar mensajes.'})});continue;}if(job.event==='resena'){await rest('plop_notifications?id=eq.'+job.id,{method:'PATCH',body:JSON.stringify({status:'sent',last_error:'Reseña gestionada por la automatización comercial consentida'})});continue;}const code=o.code;const urgent=o.contact.urgent?' · Consulta urgente':'';const text=`Pedido ${code}${urgent}\n${o.items.map((i:any)=>`${i.quantity} × ${i.name}`).join('\n')}\nTotal: $${o.total}\nSeña: $${o.deposit}\nFecha: ${o.contact.date}\nEstado: ${o.status}`;
    const customerEvent=['seña_pendiente','saldo_pendiente','confirmacion_cliente','resena'].includes(job.event);const to=customerEvent?(o.contact.email?[o.contact.email]:[]):(conf.contactEmail?[conf.contactEmail]:[]);if(!to.length)throw Error('El cliente no informó email; usar WhatsApp manual.');
    const r=await transport('https://api.resend.com/emails',{method:'POST',headers:{Authorization:'Bearer '+env.RESEND_API_KEY,'Content-Type':'application/json','Idempotency-Key':job.dedupe_key},body:JSON.stringify({from:env.EMAIL_FROM,to,subject:`Plop · ${job.event.replaceAll('_',' ')} · ${code}`,text})});if(!r.ok)throw Error('Proveedor email rechazó el aviso');
    await rest('plop_notifications?id=eq.'+job.id,{method:'PATCH',body:JSON.stringify({status:'sent',sent_at:new Date().toISOString(),last_error:null})});sent++;
   }catch(e){await rest('plop_notifications?id=eq.'+job.id,{method:'PATCH',body:JSON.stringify({status:'failed',last_error:e instanceof Error?e.message:'Error enviando'})});}}
  return {sent,queued,pendingConfiguration:false,...extras,...whatsapp};}
 return async function handler(req:Request){const url=new URL(req.url);const path=url.pathname.replace(/^.*\/plop-v2/,'').replace(/^\/api/,'')||'/';const origin=req.headers.get('origin');const cors:Record<string,string>={'Access-Control-Allow-Headers':'authorization,apikey,content-type,x-order-token','Access-Control-Allow-Methods':'GET,POST,PATCH,OPTIONS','Vary':'Origin'};if(origin&&allowedOrigin(origin))cors['Access-Control-Allow-Origin']=origin;
 const respond=(data:unknown,status=200)=>Response.json(data,{status,headers:{...cors,'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
 if(req.method==='OPTIONS')return new Response(null,{status:204,headers:cors});if(origin&&!allowedOrigin(origin))return respond({error:'Origen no permitido'},403);
 try{
 if(['POST','PATCH'].includes(req.method))req=await boundedRequest(req,path==='/orders'?27000000:['/receipt','/review'].includes(path)?5300000:40000);
 if(path==='/admin/delete-order'&&req.method==='POST'){const actor=await user(req,true);const body=z.object({id:z.string().uuid(),code:z.string().min(1).max(100),confirm:z.literal(true)}).strict().parse(await read(req));const rows=await rest('plop_orders?id=eq.'+body.id+'&select=id,code');if(!rows[0]||rows[0].code!==body.code)throw new HttpError(404,'No encontramos ese pedido. Actualizá la lista.');await rest('rpc/plop_delete_order',{method:'POST',body:JSON.stringify({p_order:body.id,p_actor:actor.id,p_code:body.code})});return respond({ok:true});}
 if(path==='/admin/session'&&req.method==='GET'){await user(req,true);return respond({authorized:true});}
 const workflow=await workflowRoute(req,path,url,rest,user,read);if(workflow)return respond(workflow);
 const edited=await orderEditRoute(req,path,url,rest,user,read);if(edited)return respond(edited);
 const capacity=await capacityRoute(req,path,url,rest,user,read);if(capacity)return respond(capacity);
 const marketing=await dispatchMarketing(req,path,url,{rest,user,rate,read,products,config,env,transport,normalizePhone:normalizedPhone,checkFile,orderFor});if(marketing)return respond(marketing.data,marketing.status||200);
 if(path==='/catalog'&&req.method==='GET'){const authSettings=await transport(env.SUPABASE_URL+'/auth/v1/settings',{headers:{apikey:env.SUPABASE_ANON_KEY},signal:AbortSignal.timeout(12000)}).then(r=>r.json());return respond({products:await products(),...await config(),checkoutEnabled:authSettings.external?.anonymous_users===true});}
 if(path==='/logout'&&req.method==='POST'){await user(req,true);const r=await transport(env.SUPABASE_URL+'/auth/v1/logout?scope=local',{method:'POST',headers:{apikey:env.SUPABASE_ANON_KEY,Authorization:req.headers.get('Authorization')!},signal:AbortSignal.timeout(12000)});if(!r.ok)throw new HttpError(503,'Cerramos el panel en este navegador, pero no pudimos cerrar la sesión remota. Volvé a ingresar y a salir cuando recuperes conexión.');return respond({ok:true});}
 if(path==='/session'&&req.method==='POST'){await rate(req,'session',20,3600);const r=await transport(env.SUPABASE_URL+'/auth/v1/signup',{method:'POST',headers:{apikey:env.SUPABASE_ANON_KEY,'Content-Type':'application/json'},body:'{}'});const d=await r.json();if(!r.ok)throw new HttpError(503,'No pudimos iniciar el pedido online. Tu selección sigue guardada; coordiná por WhatsApp.');return respond(d);}
 if(path==='/recover'&&req.method==='POST'){await rate(req,'recover',5,3600);const body=await read(req);const email=z.string().trim().email().max(160).parse(body.email).toLowerCase();if(await allowedStaff(email)){const site='https://plop-recibidas.pages.dev';const r=await transport(env.SUPABASE_URL+'/auth/v1/recover?redirect_to='+encodeURIComponent(site+'/admin/recuperar'),{method:'POST',headers:{apikey:env.SUPABASE_ANON_KEY,'Content-Type':'application/json'},body:JSON.stringify({email}),signal:AbortSignal.timeout(15000)});if(!r.ok)throw new HttpError(503,'No pudimos solicitar el enlace. Esperá unos minutos y volvé a intentar.');}return respond({ok:true});}
 if(path==='/recover/password'&&req.method==='POST'){await rate(req,'recover-password',5,300);await user(req,true);const b=await read(req);const password=z.string().max(256).parse(b.password);await checkNewPassword(password,transport);const r=await transport(env.SUPABASE_URL+'/auth/v1/user',{method:'PUT',headers:{apikey:env.SUPABASE_ANON_KEY,Authorization:req.headers.get('Authorization')!,'Content-Type':'application/json'},body:JSON.stringify({password}),signal:AbortSignal.timeout(15000)});if(!r.ok)throw new HttpError(400,'El enlace venció o la contraseña no cumple los requisitos. Solicitá un enlace nuevo.');return respond({ok:true});}
