export type WhatsAppEnv={WHATSAPP_ACCESS_TOKEN?:string;WHATSAPP_PHONE_NUMBER_ID?:string;WHATSAPP_GRAPH_VERSION?:string;WHATSAPP_ORDER_TEMPLATE?:string;WHATSAPP_TEMPLATE_LANGUAGE?:string;WHATSAPP_ORDER_RECIPIENT?:string;SITE_URL?:string};
function validRecipient(value:string|undefined){return /^[1-9]\d{7,14}$/.test(value||'');}
export function whatsappConfigured(env:WhatsAppEnv){return !!(env.WHATSAPP_ACCESS_TOKEN&&/^\d+$/.test(env.WHATSAPP_PHONE_NUMBER_ID||'')&&/^v\d+\.\d+$/.test(env.WHATSAPP_GRAPH_VERSION||'')&&/^[a-z0-9_]+$/.test(env.WHATSAPP_ORDER_TEMPLATE||''));}
export async function enqueueOrderWhatsApp(rest:(path:string,options?:RequestInit)=>Promise<any>,order:any){
