export function orderWhatsAppPayload(order:any,env:WhatsAppEnv){
 if(!validRecipient(env.WHATSAPP_ORDER_RECIPIENT))throw Error('Configurá el destinatario interno de pedidos.');
 const site=new URL(env.SITE_URL||'https://plop-recibidas.pages.dev').origin;
 const link=site+'/admin?pedido='+encodeURIComponent(order.id);
 const date=String(order.contact?.date||'A coordinar').split('-').reverse().join('/');
 return {messaging_product:'whatsapp',to:env.WHATSAPP_ORDER_RECIPIENT,type:'template',template:{name:env.WHATSAPP_ORDER_TEMPLATE,language:{code:env.WHATSAPP_TEMPLATE_LANGUAGE||'es_AR'},components:[{type:'body',parameters:[order.code,String(order.total),String(order.deposit),date,link].map(text=>({type:'text',text}))}]}};
