 else if(b.action==='moderate'){const d=z.object({id:z.string().uuid(),approve:z.boolean()}).parse(b);const review=(await rest('plop_reviews?id=eq.'+d.id+'&select=*'))[0];if(!review||!review.consent)throw new HttpError(400,'La reseña no tiene permiso de publicación.');let photoURL=null;if(!d.approve&&review.public_photo_url){const deletion=await transport(env.SUPABASE_URL+'/storage/v1/object/plop-review-approved',{method:'DELETE',headers:srv,body:JSON.stringify({prefixes:[review.id]})});if(!deletion.ok)throw new HttpError(503,'No pudimos retirar la foto publicada. Intentá nuevamente.');}if(d.approve&&review.photo_path){const r=await transport(env.SUPABASE_URL+'/storage/v1/object/plop-review-private/'+review.photo_path,{headers:srv});if(!r.ok)throw new HttpError(503,'No pudimos leer la foto');const bytes=await r.arrayBuffer(),type=r.headers.get('Content-Type')||'image/jpeg';const target=review.id;const upload=await transport(env.SUPABASE_URL+'/storage/v1/object/plop-review-approved/'+target,{method:'POST',headers:{...srv,'Content-Type':type,'x-upsert':'true'},body:bytes});if(!upload.ok)throw new HttpError(503,'No pudimos publicar la foto');photoURL=env.SUPABASE_URL+'/storage/v1/object/public/plop-review-approved/'+target;}await rest('plop_reviews?id=eq.'+d.id,{method:'PATCH',body:JSON.stringify({status:d.approve?'approved':'rejected',moderated_by:u.id,public_photo_url:photoURL})});}
 else if(b.action==='marketing_message'){const d=z.object({contacts:z.array(z.string().uuid()).min(1).max(100),subject:z.string().min(2).max(150),message:z.string().min(5).max(2000),campaignId:z.string().uuid()}).parse(b);const contacts=await rest('plop_contacts?marketing_consent=eq.true&select=*');for(const contact of eligibleRecipients(contacts,d.contacts)){await rest('plop_marketing_jobs?on_conflict=dedupe_key',{method:'POST',headers:{Prefer:'resolution=ignore-duplicates'},body:JSON.stringify({contact_id:contact.id,kind:'campaign',subject:d.subject,message:d.message.replaceAll('{nombre}',contact.name),dedupe_key:d.campaignId+':'+contact.id})});}}
 else throw new HttpError(400,'Acción no válida');return {data:{ok:true}};}
 return null;
}
export function eligibleRecipients(contacts:any[],ids:string[]){return contacts.filter(c=>c.marketing_consent===true&&ids.includes(c.id));}
export async function processMarketing(c:Context){const {rest,env,transport}=c;for(const table of ['plop_marketing_jobs','plop_meta_jobs'])await rest(table+'?status=eq.sending&claimed_at=lt.'+new Date(Date.now()-600000).toISOString(),{method:'PATCH',body:JSON.stringify({status:'pending'})});const conf=await c.config();let metaSent=0,marketingSent=0,queued=0;const rules=conf.marketingRules||{};
 const contacts=await rest('plop_contacts?marketing_consent=eq.true&select=*');
 if(Object.values(rules).some(v=>typeof v==='number')){const orders=await rest('plop_orders?is_test=eq.false&select=id,customer_id,status,created_at,updated_at,contact&order=created_at.desc&limit=5000');for(const contact of contacts){const recent=orders.find((o:any)=>o.customer_id===contact.id);const hours=(Date.now()-Date.parse(contact.updated_at))/3600000;let kind='',subject='',message='';
 if(rules.abandonHours!==null&&rules.abandonHours!==undefined&&contact.stage==='consulta'&&!recent&&hours>=rules.abandonHours){kind='retomar';subject='¿Retomamos tu idea para la recibida?';message=`Hola ${contact.name}, si todavía estás buscando ideas para tu recibida, el equipo Plop está para ayudarte.`;}
 if(recent?.status==='entregado'&&rules.reactivationDays!==null&&rules.reactivationDays!==undefined&&(Date.now()-Date.parse(recent.updated_at))/86400000>=rules.reactivationDays){kind='reactivacion';subject='Nuevas ideas de Plop';message=`Hola ${contact.name}, tenemos nuevas ideas para celebrar y compartir. Podés ver el catálogo cuando quieras.`;}
 if(recent?.status==='entregado'&&rules.reviewDays!==null&&rules.reviewDays!==undefined&&(Date.now()-Date.parse(recent.updated_at))/86400000>=rules.reviewDays){kind='resena';subject='¿Cómo fue tu experiencia con Plop?';message=`Hola ${contact.name}, nos gustaría conocer tu experiencia. Podés compartir una reseña desde el enlace privado de tu pedido.`;}
 const until=(Date.parse(contact.graduation_date+'T12:00:00-03:00')-Date.now())/86400000;if(rules.peakDays!==null&&rules.peakDays!==undefined&&!recent&&until>=0&&until<=rules.peakDays){kind='recibida_cerca';subject='Se acerca tu gran día';message=`Hola ${contact.name}, tu fecha de recibida está cerca. Si querés preparar los detalles, podemos ayudarte a elegir tu Plop.`;}
 if(kind){await rest('plop_marketing_jobs?on_conflict=dedupe_key',{method:'POST',headers:{Prefer:'resolution=ignore-duplicates'},body:JSON.stringify({contact_id:contact.id,kind,subject,message,dedupe_key:'auto:'+kind+':'+contact.id+':'+(recent?.id||contact.graduation_date)})});queued++;}}}
 if(env.RESEND_API_KEY&&env.EMAIL_FROM){const jobs=await rest('plop_marketing_jobs?status=in.(pending,failed)&attempts=lt.5&select=*&order=created_at.asc&limit=20');for(const job of jobs){const contact=contacts.find((x:any)=>x.id===job.contact_id);if(!contact?.marketing_consent||!contact.email){await rest('plop_marketing_jobs?id=eq.'+job.id,{method:'PATCH',body:JSON.stringify({status:'skipped',last_error:'Sin consentimiento vigente o sin email'})});continue;}const claim=await rest('plop_marketing_jobs?id=eq.'+job.id+'&status=in.(pending,failed)',{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({status:'sending',claimed_at:new Date().toISOString(),attempts:job.attempts+1})});if(!claim.length)continue;
 try{const r=await transport('https://api.resend.com/emails',{method:'POST',headers:{Authorization:'Bearer '+env.RESEND_API_KEY,'Content-Type':'application/json','Idempotency-Key':job.dedupe_key},body:JSON.stringify({from:env.EMAIL_FROM,to:[contact.email],subject:job.subject,text:job.message+'\n\nPara dejar de recibir novedades: '+(env.SITE_URL||'https://plop-recibidas-tienda.abuzzflea1.chatgpt.site')+'/baja#'+contact.unsubscribe_key})});if(!r.ok)throw Error();await rest('plop_marketing_jobs?id=eq.'+job.id,{method:'PATCH',body:JSON.stringify({status:'sent',sent_at:new Date().toISOString(),last_error:null})});marketingSent++;}catch{await rest('plop_marketing_jobs?id=eq.'+job.id,{method:'PATCH',body:JSON.stringify({status:'pending',last_error:'Proveedor email no disponible'})})}}}
 if(env.META_ACCESS_TOKEN&&/^v\d+\.\d+$/.test(env.META_GRAPH_VERSION||'')&&/^\d{5,30}$/.test(conf.tracking?.metaPixel||'')){const jobs=await rest('plop_meta_jobs?status=in.(pending,failed)&attempts=lt.5&select=*&limit=20');for(const job of jobs){const claim=await rest('plop_meta_jobs?event_id=eq.'+encodeURIComponent(job.event_id)+'&status=in.(pending,failed)',{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({status:'sending',claimed_at:new Date().toISOString(),attempts:job.attempts+1})});if(!claim.length)continue;try{if(!job.payload.user_data?.fbp&&!job.payload.user_data?.fbc)throw Error('Sin identificadores publicitarios consentidos');const r=await transport(`https://graph.facebook.com/${env.META_GRAPH_VERSION}/${conf.tracking.metaPixel}/events`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({data:[job.payload],access_token:env.META_ACCESS_TOKEN})});if(!r.ok)throw Error('Meta rechazó la conversión; revisar configuración');await rest('plop_meta_jobs?event_id=eq.'+encodeURIComponent(job.event_id),{method:'PATCH',body:JSON.stringify({status:'sent',last_error:null})});metaSent++;}catch(e){await rest('plop_meta_jobs?event_id=eq.'+encodeURIComponent(job.event_id),{method:'PATCH',body:JSON.stringify({status:'failed',last_error:e instanceof Error?e.message:'Error en Meta'})})}}}
 return {marketingSent,metaSent,marketingQueued:queued};
